content.new_content:
//@slider min=0.0 max=10.0 value=2.0
uniform float cycles;
//@slider min=0.0 max=5.0 value=2.0
uniform float zoom;
//@slider min=0.0 max=10.0 value=5.0
uniform float speed;
//@slider min=0.0 max=10.0 value=2.0
uniform float wave;
//@slider min=0.0 max=3.14159 value=1.5
uniform float phase;
//@slider min=0.0 max=10.0 value=3.0
uniform float stripes;
//@float min=0.0 max=10.0 value=5.0
uniform float offset;
//@rgb
uniform vec3 base_color;

void main() {
    vec2 uv = v_uv * zoom;
    float t = u_time * speed;

    // Banner effect with waves and stripes
    float wave_effect = sin(uv.x * stripes + t) * wave * 0.1;
    float banner = sin((uv.y + wave_effect + t * 0.5) * cycles) * 0.5 + 0.5;

    // Add stripes
    banner *= 0.5 + 0.5 * sin(uv.y * stripes * 3.14 + t);

    // Add phase offset
    banner = sin(banner * 3.14 + phase);

    // Mix with base color
    vec3 color = mix(vec3(0.0), base_color, abs(banner));

    // Add some animation offset
    color += vec3(offset * 0.01) * sin(t + uv.xy);

    fragColor = vec4(color, 1.0);
}
